pub fn check_p61970_600_2_equipment_ap_con_simple_shacl_acdc_converter_dc_terminal_acdc_converter_dc_ter_etc(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    const ALLOWED: &[&str] = &["DCPolarityKind.middle", "DCPolarityKind.positive", "DCPolarityKind.negative"];
    for mrid in dataset.by_type.get("ACDCConverterDCTerminal").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::ACDCConverterDCTerminal>() {
            Some(o) => o, None => continue,
        };
        if obj.polarity.is_none() { continue; }
        if !ALLOWED.contains(&obj.polarity.as_ref().map_or("", |u| u.uri.as_str())) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "eq:ACDCConverterDCTerminal.polarity-datatype".to_string(),
                class:       "ACDCConverterDCTerminal".to_string(),
                property:    "ACDCConverterDCTerminal.polarity".to_string(),
                message:     "The datatype is not IRI (Internationalized Resource Identifier) or it is enumerated value not part of the profile.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "ACDCConverterDCTerminal.polarity-datatype".to_string(),
                description: "This constraint validates the datatype of the property (attribute).".to_string(),
            });
        }
    }
    violations
}

