pub fn check_p61970_600_2_equipment_ap_con_simple_shacl_dc_converter_unit_dc_converter_unit_operation_mo_etc(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    const ALLOWED: &[&str] = &["DCConverterOperatingModeKind.bipolar", "DCConverterOperatingModeKind.monopolarGroundReturn", "DCConverterOperatingModeKind.monopolarMetallicReturn"];
    for mrid in dataset.by_type.get("DCConverterUnit").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::DCConverterUnit>() {
            Some(o) => o, None => continue,
        };
        if obj.operation_mode.is_none() { continue; }
        if !ALLOWED.contains(&obj.operation_mode.as_ref().map_or("", |u| u.uri.as_str())) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "eq:DCConverterUnit.operationMode-datatype".to_string(),
                class:       "DCConverterUnit".to_string(),
                property:    "DCConverterUnit.operationMode".to_string(),
                message:     "The datatype is not IRI (Internationalized Resource Identifier) or it is enumerated value not part of the profile.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "DCConverterUnit.operationMode-datatype".to_string(),
                description: "This constraint validates the datatype of the property (attribute).".to_string(),
            });
        }
    }
    violations
}

