pub fn check_p61970_600_2_equipment_ap_con_simple_shacl_fault_indicator_auxiliary_equipment_terminal_has_etc(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("FaultIndicator").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::FaultIndicator>() {
            Some(o) => o, None => continue,
        };
        let ref_mrid = match obj.base.terminal.as_ref() {
            Some(r) => r.mrid.trim_start_matches('#'), None => continue,
        };
        if let Some(ref_entry) = dataset.entries.get(ref_mrid) {
            let allowed: &[&str] = &["Terminal"];
            if !allowed.contains(&ref_entry.element.type_name()) {
                violations.push(Violation {
                    object_id:   mrid.clone(),
                    rule_id:     "eq:AuxiliaryEquipment.Terminal-valueType".to_string(),
                    class:       "FaultIndicator".to_string(),
                    property:    "AuxiliaryEquipment.Terminal".to_string(),
                    message:     "One of the following does not conform: 1) The value type shall be IRI; 2) The value type shall be an instance of the class: cim:Terminal".to_string(),
                    severity:    "sh:Violation".to_string(),
                    name:        "AuxiliaryEquipment.Terminal-valueType".to_string(),
                    description: "This constraint validates the value type of the association at the used direction.".to_string(),
                });
            }
        }
    }
    violations
}

