pub fn check_p61970_600_2_equipment_ap_con_simple_shacl_hydro_generating_unit_hydro_generating_unit_hydr_etc_2(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("HydroGeneratingUnit").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::HydroGeneratingUnit>() {
            Some(o) => o, None => continue,
        };
        let ref_mrid = match obj.hydro_power_plant.as_ref() {
            Some(r) => r.mrid.trim_start_matches('#'), None => continue,
        };
        if let Some(ref_entry) = dataset.entries.get(ref_mrid) {
            let allowed: &[&str] = &["HydroPowerPlant"];
            if !allowed.contains(&ref_entry.element.type_name()) {
                violations.push(Violation {
                    object_id:   mrid.clone(),
                    rule_id:     "eq:HydroGeneratingUnit.HydroPowerPlant-valueType".to_string(),
                    class:       "HydroGeneratingUnit".to_string(),
                    property:    "HydroGeneratingUnit.HydroPowerPlant".to_string(),
                    message:     "One of the following does not conform: 1) The value type shall be IRI; 2) The value type shall be an instance of the class: cim:HydroPowerPlant".to_string(),
                    severity:    "sh:Violation".to_string(),
                    name:        "HydroGeneratingUnit.HydroPowerPlant-valueType".to_string(),
                    description: "This constraint validates the value type of the association at the used direction.".to_string(),
                });
            }
        }
    }
    violations
}

