pub fn check_p61970_600_2_equipment_ap_con_simple_shacl_operational_limit_set_operational_limit_set_equi_etc_2(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("OperationalLimitSet").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::OperationalLimitSet>() {
            Some(o) => o, None => continue,
        };
        let ref_mrid = match obj.equipment.as_ref() {
            Some(r) => r.mrid.trim_start_matches('#'), None => continue,
        };
        if let Some(ref_entry) = dataset.entries.get(ref_mrid) {
            let allowed: &[&str] = &["HydroPump", "GeneratingUnit", "SurgeArrester", "WaveTrap", "FaultIndicator", "Clamp", "SeriesCompensator", "Switch", "Ground", "PowerTransformer", "DCSeriesDevice", "DCGround", "DCSwitch", "DCShunt", "DCBusbar", "DCLineSegment", "DCChopper", "PowerElectronicsWindUnit", "BatteryUnit", "PhotoVoltaicUnit", "SolarGeneratingUnit", "ThermalGeneratingUnit", "WindGeneratingUnit", "NuclearGeneratingUnit", "HydroGeneratingUnit", "PotentialTransformer", "PostLineSensor", "CurrentTransformer", "EnergySource", "EnergyConsumer", "GroundingImpedance", "PetersenCoil", "Junction", "BusbarSection", "EquivalentBranch", "EquivalentInjection", "EquivalentShunt", "Disconnector", "GroundDisconnector", "Fuse", "Jumper", "Cut", "ACLineSegment", "CsConverter", "VsConverter", "DCDisconnector", "DCBreaker", "StaticVarCompensator", "PowerElectronicsConnection", "ExternalNetworkInjection", "NonConformLoad", "StationSupply", "ConformLoad", "LoadBreakSwitch", "Breaker", "SynchronousMachine", "AsynchronousMachine", "LinearShuntCompensator", "NonlinearShuntCompensator", "DisconnectingCircuitBreaker"];
            if !allowed.contains(&ref_entry.element.type_name()) {
                violations.push(Violation {
                    object_id:   mrid.clone(),
                    rule_id:     "eq:OperationalLimitSet.Equipment-valueType".to_string(),
                    class:       "OperationalLimitSet".to_string(),
                    property:    "OperationalLimitSet.Equipment".to_string(),
                    message:     "One of the following occurs: 1) The value type is not IRI; 2) The value type is not the right class.".to_string(),
                    severity:    "sh:Violation".to_string(),
                    name:        "OperationalLimitSet.Equipment-valueType".to_string(),
                    description: "This constraint validates the value type of the association at the used direction.".to_string(),
                });
            }
        }
    }
    violations
}

