pub fn check_p61970_600_2_equipment_ap_con_simple_shacl_regulating_control_regulating_control_mode_in(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    const ALLOWED: &[&str] = &["RegulatingControlModeKind.powerFactor", "RegulatingControlModeKind.activePower", "RegulatingControlModeKind.temperature", "RegulatingControlModeKind.reactivePower", "RegulatingControlModeKind.admittance", "RegulatingControlModeKind.currentFlow", "RegulatingControlModeKind.timeScheduled", "RegulatingControlModeKind.voltage"];
    for mrid in dataset.by_type.get("RegulatingControl").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::RegulatingControl>() {
            Some(o) => o, None => continue,
        };
        if obj.mode.is_none() { continue; }
        if !ALLOWED.contains(&obj.mode.as_ref().map_or("", |u| u.uri.as_str())) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "eq:RegulatingControl.mode-datatype".to_string(),
                class:       "RegulatingControl".to_string(),
                property:    "RegulatingControl.mode".to_string(),
                message:     "The datatype is not IRI (Internationalized Resource Identifier) or it is enumerated value not part of the profile.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "RegulatingControl.mode-datatype".to_string(),
                description: "This constraint validates the datatype of the property (attribute).".to_string(),
            });
        }
    }
    violations
}

