pub fn check_p61970_600_2_equipment_ap_con_simple_shacl_solar_generating_unit_generating_unit_gen_contro_etc(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    const ALLOWED: &[&str] = &["GeneratorControlSource.onAGC", "GeneratorControlSource.offAGC", "GeneratorControlSource.plantControl", "GeneratorControlSource.unavailable"];
    for mrid in dataset.by_type.get("SolarGeneratingUnit").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::SolarGeneratingUnit>() {
            Some(o) => o, None => continue,
        };
        if obj.base.gen_control_source.is_none() { continue; }
        if !ALLOWED.contains(&obj.base.gen_control_source.as_ref().map_or("", |u| u.uri.as_str())) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "eq:GeneratingUnit.genControlSource-datatype".to_string(),
                class:       "SolarGeneratingUnit".to_string(),
                property:    "GeneratingUnit.genControlSource".to_string(),
                message:     "The datatype is not IRI (Internationalized Resource Identifier) or it is enumerated value not part of the profile.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "GeneratingUnit.genControlSource-datatype".to_string(),
                description: "This constraint validates the datatype of the property (attribute).".to_string(),
            });
        }
    }
    violations
}

