pub fn check_p61970_600_2_equipment_ap_con_simple_shacl_static_var_compensator_conducting_equipment_base_etc_2(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("StaticVarCompensator").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::StaticVarCompensator>() {
            Some(o) => o, None => continue,
        };
        let ref_mrid = match obj.base.base.base.base_voltage.as_ref() {
            Some(r) => r.mrid.trim_start_matches('#'), None => continue,
        };
        if let Some(ref_entry) = dataset.entries.get(ref_mrid) {
            let allowed: &[&str] = &["BaseVoltage"];
            if !allowed.contains(&ref_entry.element.type_name()) {
                violations.push(Violation {
                    object_id:   mrid.clone(),
                    rule_id:     "eq:ConductingEquipment.BaseVoltage-valueType".to_string(),
                    class:       "StaticVarCompensator".to_string(),
                    property:    "ConductingEquipment.BaseVoltage".to_string(),
                    message:     "One of the following does not conform: 1) The value type shall be IRI; 2) The value type shall be an instance of the class: cim:BaseVoltage".to_string(),
                    severity:    "sh:Violation".to_string(),
                    name:        "ConductingEquipment.BaseVoltage-valueType".to_string(),
                    description: "This constraint validates the value type of the association at the used direction.".to_string(),
                });
            }
        }
    }
    violations
}

